```134:143:server/router/api/v1/sse_hub.go
func (c *SSEClient) canReceive(event *SSEEvent) bool {
	switch event.Visibility {
	case store.Private:
		return c.userID == event.CreatorID || c.role == store.RoleAdmin
	case store.Public, store.Protected, "":
		return true
	default:
		return false
	}
}
```

**Why it qualifies:** Real-time memo events are filtered per connected client based on memo visibility and creator—prevents private memo updates from reaching unauthorized subscribers.

